(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-145":{scenario:{company:"Lam Kinh Finance",supervisor:{name:"Đặng Thu Trang",role:{vi:"Giám đốc Quản trị Rủi ro",en:"Chief Risk Officer"}},ref_code:"ECL-4518",title:{vi:"Đúng giai đoạn. Đúng PD. Đúng dự phòng.",en:"Right stage. Right PD. Right provision."},brief:{vi:"Bạn rà soát hồ sơ ECL-4518 tính tổn thất tín dụng dự kiến theo IFRS 9 cho một khoản vay doanh nghiệp đang quá hạn 45 ngày, chưa có bằng chứng suy giảm giá trị tín dụng. EAD 8000 triệu đồng, PD 12 tháng 4%, PD toàn thời hạn 18%, LGD 45% (số liệu mô phỏng). Bản nháp xếp khoản vay ở giai đoạn 1 và dùng PD 12 tháng. Hãy sửa giai đoạn và số ECL, rồi lập báo cáo có căn cứ gửi Ủy ban Rủi ro.",en:"You are reviewing file ECL-4518, the IFRS 9 expected credit loss for a corporate loan that is 45 days past due with no evidence of credit impairment. EAD 8000 million VND, 12-month PD 4%, lifetime PD 18%, LGD 45% (training data). The draft keeps the loan in Stage 1 and uses the 12-month PD. Correct the stage and the ECL amount, then write an evidence-based report for the Risk Committee."},reference_title:{vi:"Chính sách phân giai đoạn & tham số ECL đã duyệt · ECL-4518",en:"Approved staging policy & ECL parameters · ECL-4518"},fields:[{id:"IFRS9_STAGE",label:{vi:"Giai đoạn IFRS 9",en:"IFRS 9 stage"},initial:"STAGE 1",expected:"STAGE 2",choices:["STAGE 1","STAGE 2","STAGE 3"],reference:"Chính sách phân giai đoạn tín dụng",ref_value:{vi:"Quá hạn trên 30 ngày: tăng đáng kể rủi ro tín dụng (SICR); trên 90 ngày hoặc đã suy giảm giá trị: vỡ nợ",en:"Over 30 days past due: significant increase in credit risk (SICR); over 90 days or credit-impaired: default"},hint:{vi:"Đặt 45 ngày quá hạn cạnh hai ngưỡng 30 và 90 ngày; khoản vay chưa có bằng chứng suy giảm giá trị.",en:"Place 45 days past due against the 30 and 90 day thresholds; the loan shows no evidence of impairment."}},{id:"ECL_MVND",label:{vi:"ECL (triệu đồng)",en:"ECL (million VND)"},initial:"144",expected:"648",reference:"Bảng tham số rủi ro đã kiểm định",ref_value:{vi:"EAD 8000 triệu; PD 12 tháng 4%; PD toàn thời hạn 18%; LGD 45%",en:"EAD 8000 million; 12-month PD 4%; lifetime PD 18%; LGD 45%"},hint:{vi:"Giai đoạn 2 phải dùng PD toàn thời hạn; nhân đủ ba tham số PD, LGD và EAD.",en:"Stage 2 requires the lifetime PD; multiply all three parameters PD, LGD and EAD."}}],sop32:{vi:"Giai đoạn 1: ECL = PD 12 tháng x LGD x EAD; giai đoạn 2 và 3: ECL = PD toàn thời hạn x LGD x EAD (bài mô phỏng bỏ qua chiết khấu dòng tiền).",en:"Stage 1: ECL = 12-month PD x LGD x EAD; Stages 2 and 3: ECL = lifetime PD x LGD x EAD (the training case ignores discounting)."},context:{label:"ECL ENGINE / ECL-4518",metrics:[{label:{vi:"Số ngày quá hạn",en:"Days past due"},value:"45 DPD"},{label:{vi:"Dư nợ rủi ro EAD",en:"Exposure at default"},value:"8,000,000,000 VND"},{label:{vi:"LGD đã kiểm định",en:"Validated LGD"},value:"45%"}]},crisis:{vi:"Giám đốc khối kinh doanh nhắn: “Cứ để khoản này ở giai đoạn 1. Tuần sau tôi cho khách cơ cấu lại kỳ hạn là về trong hạn. Trích thêm 504 triệu thì quý này hụt chỉ tiêu lợi nhuận.”",en:"The business head messages you: “Keep this loan in Stage 1. Next week I will restructure the schedule so it looks current. An extra 504 million provision would miss this quarter's profit target.”"},options:{safe:{vi:"Giữ giai đoạn 2 và ECL 648 triệu theo chính sách, lưu bằng chứng ngày quá hạn, báo Giám đốc Rủi ro; khoản cơ cấu lại phải qua thời gian thử thách mới được xét chuyển giai đoạn.",en:"Keep Stage 2 and the 648 million ECL per policy, file the past-due evidence and inform the CRO; a restructured loan must pass a probation period before any stage transfer."},shortcut:{vi:"Giữ giai đoạn 1 theo đề nghị, chờ cơ cấu lại xong rồi điều chỉnh dự phòng sau.",en:"Keep Stage 1 as asked and adjust the provision after the restructuring."},wait:{vi:"Không ghi nhận gì, chờ khối kinh doanh và Ủy ban Rủi ro tự thống nhất.",en:"Record nothing and wait for the business line and the Risk Committee to agree."}},questions:{vi:["Vì sao khoản vay quá hạn 45 ngày thuộc giai đoạn 2 mà không phải giai đoạn 1 hay 3? Dữ liệu nào chứng minh nhận định của bạn?","Trình bày cách tính ECL 648 triệu đồng và rủi ro kiểm toán nếu dùng cơ cấu lại nợ để né chuyển giai đoạn."],en:["Why is a loan 45 days past due in Stage 2 rather than Stage 1 or 3? Which data supports your conclusion?","Explain how you calculated the 648 million VND ECL and the audit risk of using a restructuring to avoid a stage transfer."]},hints:{vi:["Đặt số ngày quá hạn cạnh hai ngưỡng 30 và 90 ngày trong chính sách phân giai đoạn.","Chọn đúng loại PD theo giai đoạn rồi mới nhân với LGD và EAD ở SOP mục 3.2.","Đọc SOP mục 4.2: mọi đề nghị né chuyển giai đoạn phải báo Giám đốc Rủi ro và lưu hồ sơ."],en:["Place the days past due against the 30 and 90 day thresholds in the staging policy.","Pick the PD type for the stage before multiplying by LGD and EAD in SOP 3.2.","Re-read SOP 4.2: any request to avoid a stage transfer must be escalated to the CRO and documented."]}},learning:{summary:{vi:"Chuyên viên quản trị rủi ro tài chính nhận diện, đo lường và giám sát rủi ro tín dụng, thị trường, thanh khoản và hoạt động; xây dựng, vận hành mô hình PD, LGD, EAD, tính tổn thất tín dụng dự kiến (ECL) theo IFRS 9, giá trị chịu rủi ro (VaR) và kiểm định sức chịu đựng. Nghề tạo ra cảnh báo sớm, hạn mức hợp lý và số dự phòng đáng tin cậy, đòi hỏi tư duy định lượng, hiểu chuẩn mực và bản lĩnh độc lập trước áp lực kinh doanh.",en:"A financial risk analyst identifies, measures and monitors credit, market, liquidity and operational risk; builds and runs PD, LGD and EAD models, calculates IFRS 9 expected credit loss (ECL), value at risk (VaR) and stress tests. The role delivers early warnings, sound limits and reliable provisions, and requires quantitative thinking, command of the standards and independence under business pressure."},responsibilities:{vi:["Phân giai đoạn danh mục tín dụng theo IFRS 9 và tính ECL hằng tháng.","Xây dựng, kiểm định và hiệu chỉnh mô hình PD, LGD, EAD cùng kịch bản vĩ mô.","Đo lường rủi ro thị trường và thanh khoản: VaR, độ nhạy lãi suất, khe hở kỳ hạn.","Thực hiện kiểm định sức chịu đựng và báo cáo khẩu vị rủi ro cho Ủy ban Rủi ro.","Giám sát hạn mức, cảnh báo vi phạm và đề xuất biện pháp xử lý."],en:["Stage the credit portfolio under IFRS 9 and calculate ECL every month.","Build, validate and recalibrate PD, LGD and EAD models with macro scenarios.","Measure market and liquidity risk: VaR, interest rate sensitivity, maturity gaps.","Run stress tests and report risk appetite to the Risk Committee.","Monitor limits, flag breaches and propose remediation."]},competencies:[{name:{vi:"Mô hình định lượng",en:"Quantitative modelling"},desc:{vi:"Ước lượng PD, LGD, EAD bằng thống kê, kiểm định ngược và giải thích được giới hạn của mô hình.",en:"Estimate PD, LGD and EAD with statistics, backtest them and explain each model's limits."}},{name:{vi:"Chuẩn mực IFRS 9",en:"IFRS 9 expertise"},desc:{vi:"Áp dụng tiêu chí SICR, định nghĩa vỡ nợ, thông tin dự báo tương lai và ECL ba giai đoạn.",en:"Apply SICR criteria, the default definition, forward-looking information and three-stage ECL."}},{name:{vi:"Phân tích dữ liệu rủi ro",en:"Risk data analysis"},desc:{vi:"Làm sạch, đối chiếu dữ liệu khoản vay, ngày quá hạn, tài sản bảo đảm trước khi chạy mô hình.",en:"Clean and reconcile loan, past-due and collateral data before running models."}},{name:{vi:"Độc lập & liêm chính",en:"Independence & integrity"},desc:{vi:"Giữ kết quả mô hình và chính sách trước áp lực lợi nhuận, báo cáo trung thực lên cấp có thẩm quyền.",en:"Defend model results and policy against profit pressure and report honestly to the proper authority."}},{name:{vi:"Truyền đạt rủi ro",en:"Risk communication"},desc:{vi:"Biến con số phức tạp thành thông điệp rõ ràng cho Ban điều hành và Ủy ban Rủi ro.",en:"Turn complex numbers into clear messages for executives and the Risk Committee."}}],knowledge:{vi:["IFRS 9 Công cụ tài chính: mô hình ECL ba giai đoạn, tiêu chí tăng đáng kể rủi ro tín dụng (SICR) và định nghĩa vỡ nợ.","Khung Basel II/III của Ủy ban Basel: vốn tối thiểu, đệm vốn, tỷ lệ đòn bẩy, LCR và NSFR.","Thông tư 41/2016/TT-NHNN về tỷ lệ an toàn vốn và Thông tư 11/2021/TT-NHNN về phân loại nợ, trích lập dự phòng rủi ro.","Thông tư 13/2018/TT-NHNN về hệ thống kiểm soát nội bộ và mô hình ba tuyến bảo vệ.","Đo lường rủi ro thị trường: VaR tham số, lịch sử, Monte Carlo và kiểm định ngược.","Kiểm định sức chịu đựng và xây dựng kịch bản vĩ mô cho dự báo có tính đến tương lai."],en:["IFRS 9 Financial Instruments: the three-stage ECL model, significant increase in credit risk (SICR) and the default definition.","The Basel II/III framework: minimum capital, buffers, leverage ratio, LCR and NSFR.","Circular 41/2016/TT-NHNN on capital adequacy and Circular 11/2021/TT-NHNN on loan classification and provisioning.","Circular 13/2018/TT-NHNN on internal control systems and the three lines of defence.","Market risk measurement: parametric, historical and Monte Carlo VaR with backtesting.","Stress testing and building macro scenarios for forward-looking estimates."]},tools:["Python / R","SQL risk data mart","ECL calculation engine","Stress testing model","Spreadsheet models","BI risk dashboard"],tools_en:["Python / R","SQL risk data mart","ECL calculation engine","Stress testing model","Spreadsheet models","BI risk dashboard"],kpis:{vi:["Tỷ lệ báo cáo ECL nộp đúng hạn và không phải điều chỉnh sau kiểm toán.","Sai số dự báo PD so với tỷ lệ vỡ nợ thực tế trong kiểm định ngược.","Số vi phạm hạn mức được phát hiện và báo cáo trong 24 giờ.","Số phát hiện trọng yếu của kiểm toán về mô hình rủi ro (mục tiêu bằng 0)."],en:["Share of ECL reports filed on time with no post-audit adjustments.","PD forecast error versus actual default rates in backtesting.","Limit breaches detected and reported within 24 hours.","Material audit findings on risk models (target zero)."]},day:[{time:"08:00",vi:"Kiểm tra dữ liệu dư nợ, ngày quá hạn tải về từ hệ thống lõi qua đêm.",en:"Check overnight exposure and past-due data loaded from the core system."},{time:"09:30",vi:"Chạy phân giai đoạn IFRS 9 và rà soát các khoản chuyển giai đoạn bất thường.",en:"Run IFRS 9 staging and review unusual stage transfers."},{time:"11:00",vi:"Cập nhật VaR danh mục kinh doanh và đối chiếu với hạn mức đã duyệt.",en:"Update trading book VaR and compare it with approved limits."},{time:"14:00",vi:"Họp với khối kinh doanh giải trình kết quả ECL và các khoản cần theo dõi.",en:"Meet the business line to explain ECL results and watch-list loans."},{time:"16:30",vi:"Soạn báo cáo rủi ro tuần và đề xuất kịch bản kiểm định sức chịu đựng.",en:"Draft the weekly risk report and propose stress test scenarios."}],mistakes:{vi:["Giữ khoản vay quá hạn trên 30 ngày ở giai đoạn 1 mà không có lý do bác bỏ hợp lệ.","Dùng PD 12 tháng cho khoản vay giai đoạn 2, làm thiếu dự phòng.","Chấp nhận cơ cấu lại nợ để đưa khoản vay về giai đoạn 1 ngay, bỏ qua thời gian thử thách."],en:["Keeping a loan over 30 days past due in Stage 1 without a valid rebuttal.","Using the 12-month PD for a Stage 2 loan, leaving the provision short.","Accepting a restructuring to move a loan straight back to Stage 1, skipping the probation period."]},career:[{vi:"Chuyên viên phân tích rủi ro",en:"Risk analyst"},{vi:"Chuyên viên cao cấp mô hình rủi ro",en:"Senior risk modelling specialist"},{vi:"Trưởng phòng Quản lý rủi ro tín dụng / thị trường",en:"Head of credit or market risk"},{vi:"Giám đốc Quản trị Rủi ro (CRO)",en:"Chief Risk Officer (CRO)"}],glossary:[{term:"PD",vi:"Xác suất vỡ nợ của khách hàng trong 12 tháng hoặc toàn thời hạn khoản vay.",en:"Probability that a borrower defaults over 12 months or the loan lifetime."},{term:"LGD",vi:"Tỷ lệ tổn thất khi vỡ nợ: phần dư nợ không thu hồi được sau khi xử lý tài sản bảo đảm.",en:"Loss given default: the share of exposure not recovered after collateral is realised."},{term:"EAD",vi:"Dư nợ rủi ro tại thời điểm vỡ nợ, gồm dư nợ hiện tại và phần hạn mức dự kiến được rút.",en:"Exposure at default, including the drawn balance and expected future drawdowns."},{term:"SICR",vi:"Tăng đáng kể rủi ro tín dụng kể từ ghi nhận ban đầu, căn cứ chuyển sang giai đoạn 2.",en:"Significant increase in credit risk since initial recognition, the trigger for Stage 2."},{term:"VaR",vi:"Giá trị chịu rủi ro: mức lỗ tối đa ước tính trong một kỳ ở một độ tin cậy cho trước.",en:"Value at risk: the estimated maximum loss over a horizon at a given confidence level."}],quiz:[{q:{vi:"Theo IFRS 9, giả định có thể bác bỏ về tăng đáng kể rủi ro tín dụng áp dụng khi khoản vay quá hạn bao lâu?",en:"Under IFRS 9, the rebuttable presumption of a significant increase in credit risk applies after how many days past due?"},options:{vi:["Trên 10 ngày","Trên 60 ngày","Trên 30 ngày","Trên 180 ngày"],en:["More than 10 days","More than 60 days","More than 30 days","More than 180 days"]},answer:2,explain:{vi:"IFRS 9 giả định rủi ro tín dụng tăng đáng kể khi khoản thanh toán quá hạn trên 30 ngày, trừ khi có bằng chứng hợp lý bác bỏ.",en:"IFRS 9 presumes a significant increase in credit risk when payments are more than 30 days past due, unless reasonable evidence rebuts it."}},{q:{vi:"Khoản vay giai đoạn 2 có EAD 5000 triệu, PD toàn thời hạn 10%, LGD 40%. ECL là bao nhiêu?",en:"A Stage 2 loan has EAD 5000 million, lifetime PD 10% and LGD 40%. What is the ECL?"},options:{vi:["200 triệu","500 triệu","2000 triệu","20 triệu"],en:["200 million","500 million","2000 million","20 million"]},answer:0,explain:{vi:"ECL = 10% x 40% x 5000 = 200 triệu đồng (bỏ qua chiết khấu).",en:"ECL = 10% x 40% x 5000 = 200 million (ignoring discounting)."}},{q:{vi:"VaR 1 ngày ở độ tin cậy 99% bằng 2 tỷ đồng nghĩa là gì?",en:"What does a 1-day 99% VaR of 2 billion VND mean?"},options:{vi:["Lỗ tối đa chắc chắn là 2 tỷ","Lãi kỳ vọng mỗi ngày là 2 tỷ","Hạn mức đầu tư là 2 tỷ","Chỉ có 1% khả năng lỗ một ngày vượt 2 tỷ trong điều kiện thị trường bình thường"],en:["The loss can never exceed 2 billion","Expected daily profit is 2 billion","The investment limit is 2 billion","There is only a 1% chance a daily loss exceeds 2 billion in normal markets"]},answer:3,explain:{vi:"VaR là ngưỡng lỗ ở độ tin cậy cho trước, không phải mức lỗ tối đa tuyệt đối; cần bổ sung kiểm định sức chịu đựng.",en:"VaR is a loss threshold at a confidence level, not an absolute maximum; stress tests are still needed."}},{q:{vi:"Khối kinh doanh đề nghị chỉnh tham số PD để giảm dự phòng cho kịp chỉ tiêu. Bạn làm gì?",en:"The business line asks you to tweak the PD to cut provisions and hit targets. What do you do?"},options:{vi:["Chỉnh nhẹ vì khó bị phát hiện","Giữ tham số đã kiểm định, ghi nhận đề nghị và báo Giám đốc Rủi ro","Chờ kiểm toán tự phát hiện","Chuyển việc cho đồng nghiệp"],en:["Tweak it slightly since it is hard to detect","Keep the validated parameters, record the request and inform the CRO","Wait for the auditors to notice","Hand the task to a colleague"]},answer:1,explain:{vi:"Chức năng rủi ro phải độc lập; mọi thay đổi tham số chỉ theo quy trình kiểm định và phê duyệt chính thức.",en:"The risk function must be independent; parameters change only through formal validation and approval."}}]}}})})(window.KKR);
